window.__QUIZ_DATA__={"categories":[{"key":"kernel","name":"Linux 内核","file":"kernel.json","count":16,"desc":"进程/内存/并发/中断/驱动模型。答不全数字，等于没做过内核。"},{"key":"gpu","name":"GPU / CUDA","file":"gpu.json","count":16,"desc":"UMD/KMD 分层、显存、命令提交、同步、MPS/MIG。NVIDIA 方向的核心。"},{"key":"virt","name":"虚拟化","file":"virt.json","count":12,"desc":"KVM/QEMU、VT-x/EPT、VFIO/SR-IOV、virtio、GPU 虚拟化。"},{"key":"net","name":"计算机网络","file":"net.json","count":12,"desc":"TCP 状态机、epoll、零拷贝、RDMA、收包路径。"},{"key":"cpp","name":"C / C++","file":"cpp.json","count":16,"desc":"对象模型、内存序、RAII、移动语义、UB。基本盘，权重最高。"},{"key":"python","name":"Python","file":"python.json","count":12,"desc":"GIL、对象模型、生成器、C 扩展。工具链与脚本层。"},{"key":"sysdebug","name":"调试与性能","file":"sysdebug.json","count":12,"desc":"perf、ftrace、eBPF、lockdep、kdump。面试里最能区分真做过和只知道的人。"}],"questions":{"kernel":[{"id":"k-001","q":"x86-64 在默认的四级页表配置下，线性地址是多少位？","opts":["32 位","40 位","48 位","64 位"],"a":2,"exp":"四级页表按 9+9+9+9+12 拆位，合计 48 位。剩下高 16 位必须做符号扩展（第 47 位决定）。开启 5-level paging（LA57）后扩展到 57 位。","level":"高频","tags":["内存管理","页表"]},{"id":"k-002","q":"x86-64 上内核栈的默认大小是多少？","opts":["4 KB","8 KB","16 KB","32 KB"],"a":2,"exp":"THREAD_SIZE_ORDER 默认为 2，即 4 个 4KB 页 = 16KB。中断/异常上下文共用当前任务的内核栈（不进线程），所以栈里写的临时数据要考虑并发与深度。","level":"高频","tags":["进程","栈"]},{"id":"k-003","q":"在 Linux 内核里，进程和线程在数据结构上是什么关系？","opts":["线程是 task_struct 的子结构，进程是父结构","二者都用 task_struct 描述，区别只在 clone() 时是否共享地址空间等资源","进程用 task_struct，线程用单独的 thread_struct","内核不区分，靠用户态 pthread 库自己实现"],"a":1,"exp":"Linux 内核不设独立的 thread 结构，统一是 task_struct。传 CLONE_VM|CLONE_FS|CLONE_FILES|CLONE_SIGHAND|CLONE_THREAD 就得到「线程」，不传就是独立进程。这也解释了为什么创建线程和创建进程在内核里开销相近。","level":"高频","tags":["进程","调度"]},{"id":"k-004","q":"CFS 调度器选择下一个可运行任务时，依据的是哪个数据结构上的什么值？","opts":["链表，按静态优先级排序","红黑树，取 vruntime 最小的节点","哈希表，按 CPU 亲和性索引","最小堆，按 nice 值排序"],"a":1,"exp":"CFS 用红黑树按 vruntime 排序，最左节点即 vruntime 最小者。vruntime 累加的是「实际运行时间 × 权重因子」，nice 值越高权重越低、vruntime 增长越快，于是被排到后面。","level":"高频","tags":["调度","CFS"]},{"id":"k-005","q":"为什么中断上下文里不能睡眠（调用可能睡眠的函数）？","opts":["中断上下文没有 task_struct，无法调度","中断上下文不隶属任何进程，睡眠后没有可恢复的上下文，且会阻塞该 CPU 上的其他中断/软中断","内核配置默认禁止，可以手工打开","睡眠会让中断控制器丢中断"],"a":1,"exp":"硬中断在「借用」被打断任务的内核栈上运行，且此时 preempt_count > 0、本 CPU 中断可能已关。schedule() 在原子上下文里会触发 `BUG: scheduling while atomic`。正确做法是把可能阻塞的工作推到 workqueue。","level":"高频","tags":["中断","并发"]},{"id":"k-006","q":"关于 spinlock 与 mutex，下列说法正确的是？","opts":["spinlock 可以睡眠，mutex 不能睡眠","spinlock 忙等、持锁期间不能睡眠，可用于中断上下文；mutex 会睡眠、只能用于进程上下文","两者都可用于中断上下文","mutex 就是带超时的 spinlock"],"a":1,"exp":"spinlock 持有期间会关闭抢占（在非 RT 内核上），因此不能睡眠，可用于硬中断。mutex 拿到锁失败会挂到等待队列并让出 CPU，所以只能用于允许睡眠的进程上下文。中断里要保护共享数据，用 spinlock 或 spin_lock_irqsave。","level":"高频","tags":["并发","锁"]},{"id":"k-007","q":"RCU 的读侧临界区（rcu_read_lock/rcu_read_unlock）在非抢占 RCU 下的开销大致是？","opts":["一次原子加减，与写侧竞争同一缓存行","几乎没有开销：不修改共享计数，只是编译器屏障加禁止抢占","一次系统调用","一次内存分配"],"a":1,"exp":"RCU 读侧不加锁、不改共享计数器，只做 barrier()，在可抢占内核里额外 preempt_disable()。因此读多写少的场景扩展性极好。写侧则要等所有 pre-existing 读者退出（宽限期 grace period）后才能释放旧对象。","level":"中频","tags":["并发","RCU"]},{"id":"k-008","q":"kmalloc 与 vmalloc 的核心区别是？","opts":["kmalloc 分配物理连续内存，vmalloc 只保证虚拟地址连续","kmalloc 只能用于用户态，vmalloc 只能用于内核态","vmalloc 更快但碎片更多","两者完全等价，只是历史遗留"],"a":0,"exp":"kmalloc 从 slab 分配物理连续内存，可直接给 DMA 用（配合同一设备约束），大小受 KMALLOC_MAX_CACHE_SIZE 限制。vmalloc 拼虚拟页、物理不连续，适合大块但会带来 TLB 和映射开销，且不能直接 DMA。","level":"高频","tags":["内存管理"]},{"id":"k-009","q":"GFP_ATOMIC 与 GFP_KERNEL 的区别，最主要体现在？","opts":["GFP_ATOMIC 分配更快","GFP_KERNEL 可能睡眠并回收内存，因此只能在允许睡眠的上下文使用；GFP_ATOMIC 不睡眠、更易失败，可用于中断上下文","GFP_ATOMIC 只能分配小于 4KB","GFP_KERNEL 会清零内存"],"a":1,"exp":"GFP_KERNEL 走直接回收、可能等待 IO，所以在原子上下文里会 BUG。GFP_ATOMIC 只从空闲池拿，拿不到就返回 NULL，因此必须检查返回值。中断、持 spinlock 时用 GFP_ATOMIC。","level":"高频","tags":["内存管理","中断"]},{"id":"k-010","q":"内核访问用户态指针为什么不能直接用 memcpy？","opts":["memcpy 在内核里不存在","用户指针不可信，可能未映射，直接解引用会触发 oops；copy_from_user 做了 access_ok 校验并用异常表兜住缺页","因为用户内存可能是高端内存","因为需要加锁"],"a":1,"exp":"用户可能传一个野指针（甚至指向内核地址）。copy_from_user / copy_to_user 先做 access_ok 检查范围，拷贝时用 extable 注册异常表，一旦缺页就把失败转成返回值而不是 panic。这是内核必要的健壮性边界。","level":"高频","tags":["驱动","安全"]},{"id":"k-011","q":"用户进程第一次写入一块刚 mmap 的匿名内存，会发生什么缺页？","opts":["major fault，需要读磁盘","minor fault，内核分配一个零页并填入页表","不会缺页，mmap 时已分配物理页","收到 SIGSEGV"],"a":1,"exp":"匿名页 mmap 只建立 VMA，不分配物理页。首次写触发写保护的零页，内核分配一个 Page Anon 并建立映射（minor fault，无磁盘 IO）。若是文件映射则可能是 major fault，需要先把 page cache 读进来。","level":"高频","tags":["内存管理","缺页"]},{"id":"k-012","q":"内核把中断处理拆成 top half 与 bottom half，主要目的是？","opts":["为了支持多核","硬中断里关中断执行，必须尽快返回；把耗时部分推迟到 softirq/tasklet/workqueue，减少中断关闭时间和丢中断风险","为了让用户态能处理中断","为了节省内存"],"a":1,"exp":"top half 运行在关中断或至少关本 CPU 中断的状态下，拖久了会丢中断、增加延迟。softirq/tasklet 在中断返回后以可被中断的方式运行；workqueue 跑在内核线程里，可以睡眠。选型看是否需要睡眠。","level":"高频","tags":["中断","top-bottom"]},{"id":"k-013","q":"关于 DMA 的 coherent 映射与 streaming 映射，说法正确的是？","opts":["coherent 映射针对一块缓冲区长期使用，CPU 与设备看到一致视图，通常不可 cache 或做了 cache 维护；streaming 映射用于单次传输，需要 dma_sync_* 显式同步","两者都需要手动调用 dma_sync_single_for_cpu","streaming 映射的内存由内核自动回收","coherent 映射比 streaming 更快"],"a":0,"exp":"dma_alloc_coherent 返回长期可用的、CPU/设备一致的缓冲区（代价通常是 uncached/写合并，访问慢）。dma_map_single 是 streaming 映射，映射/解映射之间所有权转移，CPU 与设备交替访问时要用 dma_sync_single_for_cpu/device 保持 cache 一致。","level":"中频","tags":["驱动","DMA"]},{"id":"k-014","q":"spin_lock 与 spin_lock_irqsave 的选择依据是？","opts":["性能优先用 spin_lock","如果同一把锁还会在硬中断里被获取，本地必须用 spin_lock_irqsave 关中断，否则可能在持锁时被中断、中断里再抢同一把锁而死锁","spin_lock_irqsave 是给多核用的，spin_lock 是给单核用的","两者可互换"],"a":1,"exp":"死锁场景：进程上下文持锁 → 本 CPU 被中断 → 中断处理里再 spin_lock 同一把锁 → 永远自旋（中断不会返回）。所以锁若被中断路径获取，进程侧必须关本地中断。注意关的只是本 CPU 中断，跨 CPU 靠自旋。","level":"高频","tags":["并发","锁"]},{"id":"k-015","q":"VFS 中 dentry 与 inode 的关系是？","opts":["一一对应，不可分离","dentry 表示路径中的一个名字节点，inode 表示文件本身；多个 dentry（硬链接、挂载）可指向同一个 inode","inode 只存在于磁盘，dentry 只存在于内存","两者都是磁盘结构"],"a":1,"exp":"dentry 是目录项缓存（dcache），把「名字 → inode」缓存起来加速路径查找，是内存结构。inode 描述文件元数据，可来自磁盘也可纯内存（如 procfs）。硬链接就是多个 dentry 指向同一 inode。","level":"中频","tags":["文件系统","VFS"]},{"id":"k-016","q":"PREEMPT_RT 补丁与主线内核的主要差异不包括？","opts":["把大部分 spinlock 替换为可睡眠的 rt_mutex","把硬中断线程化为内核线程","提高最坏情况下的调度延迟上限","让内核栈从 16KB 变成 32KB"],"a":3,"exp":"PREEMPT_RT 的核心是降低最坏延迟：spinlock 改 rt_mutex（支持优先级继承）、中断线程化、高精度定时器、降低关抢占临界区。它与内核栈大小无关。代价是吞吐量下降。","level":"低频","tags":["调度","实时"]}],"gpu":[{"id":"g-001","q":"NVIDIA GPU 上一个 warp 包含多少个线程？","opts":["16","32","64","128"],"a":1,"exp":"从 Fermi 到 Blackwell 一直是 32 个线程为一个 warp，这是 SIMT 调度的基本单位。一个 SM 同时驻留多个 warp（上限由每 SM 的 warp slot 决定），调度器在每个周期从就绪 warp 中挑一个发射指令，以此隐藏访存与流水线延迟。","level":"高频","tags":["SM","SIMT"]},{"id":"g-002","q":"一个 thread block 最多可以有多少个线程？","opts":["512","1024","2048","取决于 SM"],"a":1,"exp":"1024 是 CUDA 的硬上限，且必须是 warp(32) 的整数倍才不浪费。但能不能同时驻留取决于资源：寄存器、共享内存、每 SM 的 block 数量上限。所以「block 开 1024」在实践中常因寄存器压力导致 occupancy 下降。","level":"高频","tags":["线程模型"]},{"id":"g-003","q":"CUDA Runtime API 与 Driver API 的关系是？","opts":["两者完全独立，互不影响","Runtime API（cudaXxx）构建在 Driver API（cuXxx）之上，前者负责上下文等样板管理，后者暴露更细粒度的控制","Driver API 是旧接口，已废弃","Runtime API 只能用于多 GPU，Driver API 只能用于单 GPU"],"a":1,"exp":"libcudart 内部调用 libcuda。Runtime 帮你隐式创建 primary context、管理模块加载；Driver 则要你显式 cuInit/cuCtxCreate/cuModuleLoad，换来对上下文、模块、内存对象的精确控制。写驱动/框架层基本都用 Driver API。","level":"高频","tags":["CUDA","API 分层"]},{"id":"g-004","q":"CUDA 中「上下文（context）」和「流（stream）」的关系是？","opts":["一个流可以跨多个上下文","上下文是资源容器（地址空间、模块、分配器状态），流是上下文内的有序任务队列；同一流内串行，不同流之间可并发","两者是同一个东西的不同叫法","上下文是线程级的，流是进程级的"],"a":1,"exp":"context 相当于 GPU 侧的「进程地址空间」，所有显存分配、模块、句柄都归属于它。stream 是 context 内的执行队列，用来表达依赖顺序。跨 stream 没有顺序保证，需要 event 或显式同步。context 的创建/销毁很贵，多线程应共享而不是各建一个。","level":"高频","tags":["CUDA","上下文","流"]},{"id":"g-005","q":"cudaMemcpyAsync 从主机内存拷贝到显存，要真正异步必须满足什么条件？","opts":["主机内存必须是页锁定（pinned / cudaMallocHost）的","必须使用默认流","必须开启 Unified Memory","目标必须是共享内存"],"a":0,"exp":"普通 pageable 内存下，驱动必须先把它搬进内部暂存缓冲，这个动作对调用线程是同步的，函数返回时数据已拷完。只有 pinned 内存才能靠 DMA 引擎在后台搬、把控制权立刻还给 CPU。代价是 pinned 内存不可换出，不能滥用。","level":"高频","tags":["CUDA","内存","DMA"]},{"id":"g-006","q":"关于 Unified Memory（cudaMallocManaged），正确的是？","opts":["数据只能被 GPU 访问","CPU 和 GPU 共用同一套虚拟地址，物理页按需在两侧迁移，迁移由页错误驱动（或预取）","它就是 pinned 内存的别名","它不需要同步"],"a":1,"exp":"cudaMallocManaged 返回的指针在 host 和 device 上都能解引用，驱动维护单一虚拟地址、物理页可落在任一侧。首次访问时若页不在本地会触发 GPU/CPU 页错误并迁移，所以「第一次跑慢、后续快」。在 Blackwell/Hopper 这类带 CPU-GPU 一致性互联的平台上语义更强，但一般 PCIe 平台上仍要小心 thrashing。","level":"高频","tags":["CUDA","统一内存","HMM"]},{"id":"g-007","q":"warp divergence（分支发散）为什么影响性能？","opts":["因为会触发重编译","因为一个 warp 共用一条指令流，分支两侧必须串行执行，且只有部分 lane 有效，无法合并访存","因为它强制回退到 CPU 执行","因为会耗尽共享内存"],"a":1,"exp":"SIMT 下一个 warp 的所有 lane 共享 PC，遇到分支就按路径序列化执行、用 mask 屏蔽不参与的 lane，总时间约为各分支时间之和。如果两侧访存地址不能合并，还会放大内存事务数。Volta 之后的独立线程调度缓解了死锁风险，但不消除发散本身的性能代价。","level":"高频","tags":["SIMT","性能"]},{"id":"g-008","q":"为了隐藏全局内存访问延迟，最有效的手段是？","opts":["提高单线程的 ILP","提高 occupancy，让 SM 有足够多的 resident warp 可切换","加大每个 block 的线程数到 1024","把数据放进 local memory"],"a":1,"exp":"GPU 靠「多 warp 轮转」而不是深度乱序来隐藏延迟。全局访存要几百个 cycle，必须有足够多就绪 warp 填满流水线。但 occupancy 不是越高越好：提高它会挤占寄存器与共享内存，可能反而降低每线程性能。正确做法是用 Nsight Compute 看 stall 原因再调。","level":"高频","tags":["性能","occupancy"]},{"id":"g-009","q":"显存带宽与容量之间的关系，下列描述正确的是？","opts":["HBM 的带宽显著高于 GDDR，靠的是更多、更宽的堆叠通道和更高的总位宽","HBM 带宽高是因为频率远高于 GDDR","显存带宽与 GPU 计算能力无关","增加显存容量必然提升带宽"],"a":0,"exp":"HBM 用 2.5D 封装把多层 DRAM 堆栈和 GPU 封在一起，通过硅中介层走超宽位宽（HBM2e/HBM3 每堆栈 1024 bit），靠位宽而非超高频率拿到带宽。以 A100 80GB 为例 HBM2e 带宽为 2039 GB/s，H100 SXM 的 HBM3 为 3.35 TB/s。带宽决定「访存受限」算子的上限。","level":"中频","tags":["HBM","显存"]},{"id":"g-010","q":"GPU 用户态驱动（UMD）与内核态驱动（KMD）的分工，最准确的描述是？","opts":["UMD 做全部硬件操作，KMD 只负责加载","KMD 负责资源与权限管理（显存分配、通道/上下文创建、中断、电源、GPU 页表），UMD 负责把 API 调用翻译成硬件命令并直接提交到 GPU 队列","UMD 跑在内核里，KMD 跑在用户态","所有命令都必须经 ioctl 由 KMD 提交"],"a":1,"exp":"现代 GPU 驱动的关键设计是「内核控制、用户态提交」：KMD 建立并授权一个 channel/context 与对应的 GPU 页表，然后 UMD 就能把命令写进映射到用户空间的 pushbuffer，敲 doorbell 让硬件取。内核不在提交热路径上，这是低延迟和高吞吐的前提。AMD amdgpu 的 ring、NVIDIA 的 channel/GPFIFO 都是这个模型。","level":"高频","tags":["驱动","UMD","KMD"]},{"id":"g-011","q":"GPU 命令提交中的「doorbell」机制，本质是什么？","opts":["一种中断，由 GPU 发给 CPU","UMD 往一个映射到用户空间的 MMIO 寄存器写入新的队尾指针，硬件据此知道有新命令可取","一种 DMA 描述符格式","一个内核系统调用"],"a":1,"exp":"doorbell 是一个 BAR 里的寄存器（每通道一个）。UMD 填好 pushbuffer、更新内存中的 write pointer，再写 doorbell 通知硬件。因为寄存器被映射进用户态，这一步不需要 ioctl。硬件收到后 DMA 读取命令。与之相对的 work pointer 由硬件回写，用户态轮询即可知道完成进度。","level":"中频","tags":["驱动","命令提交"]},{"id":"g-012","q":"CUDA Graph 主要解决什么问题？","opts":["降低 GPU 显存占用","把一串重复的 kernel/拷贝调用「录制」成图，一次提交重复回放，消除逐次 launch 的 CPU 开销","让 kernel 跑得更快","实现跨 GPU 通信"],"a":1,"exp":"小 kernel 的 launch 开销在 CPU 侧有数微秒量级，当 kernel 本身只有几微秒时，CPU 成为瓶颈（launch-bound）。Graph 把依赖关系一次性捕获、整体提交，把 N 次提交压成 1 次，还顺带让驱动做更激进的重叠与优化。注意它优化的是提交开销，不改变 kernel 内部性能。","level":"中频","tags":["CUDA","Graphs"]},{"id":"g-013","q":"MPS 与 MIG 的区别，正确的是？","opts":["MPS 是硬件分区，MIG 是软件共享","MIG 把 GPU 切分成物理隔离的若干实例（各自有独立 SM 切片、显存、缓存），MPS 让多个进程共享同一 GPU/context 空间以降低调度开销，但故障与资源并不强隔离","两者都是虚拟化方案，等价","MPS 只能用于 A100 以后"],"a":1,"exp":"MIG 是硬件级切分（A100/H100 支持，最多 7 个 slice），有独立的显存与 fault domain，适合多租户；MPS 是运行时的多进程服务，多个 client 共享一个 context，省掉 context switch 并让 kernel 并发填充空闲 SM，但一个进程 OOM 或 CUDA 错误可能拖累其他 client。","level":"中频","tags":["MPS","MIG","多租户"]},{"id":"g-014","q":"GPU 与 CPU 之间的 PCIe 传输，下列数字层次最接近实际的是？","opts":["PCIe Gen4 x16 双向约 64 GB/s（每方向约 32 GB/s）","PCIe Gen4 x16 双向约 6.4 GB/s","PCIe Gen5 x16 每方向约 256 GB/s","PCIe 带宽与代际无关"],"a":0,"exp":"Gen4 x16 理论 ~32 GB/s 每方向，实际可达 ~25 GB/s。Gen5 x16 翻倍到 ~64 GB/s 每方向。这比 HBM 的 TB/s 量级低两个数量级，所以「减少 host-device 传输」永远是最优先的优化，NVLink（H100 达 900 GB/s 双向）就是为了绕开这个瓶颈。","level":"中频","tags":["PCIe","互联"]},{"id":"g-015","q":"CUDA 的内存模型中，为什么需要 __syncthreads() 而不能依赖 volatile？","opts":["两者等价，习惯问题","__syncthreads 是 block 内屏障，既保证同步点、又提供内存序；volatile 只阻止编译器优化单个变量访问，不建立跨线程顺序，也不保证共享内存可见性","volatile 只能用于全局内存","__syncthreads 只能用于 warp 内"],"a":1,"exp":"CUDA 是弱内存模型。共享内存的写入对其他线程可见需要屏障来建立 happens-before。volatile 只让编译器每次都去内存读，不产生 barrier 语义，也不保证编译器不重排其他访存。warp 内做数据交换应优先用 __shfl_sync 系列，比共享内存加屏障更轻。","level":"中频","tags":["CUDA","内存模型","同步"]},{"id":"g-016","q":"同一个 stream 内先后 launch 的 kernel，其执行顺序保证是？","opts":["并行执行，无顺序","严格按提交顺序执行，后一个不会早于前一个开始","由硬件随机调度","只有加了 event 才有顺序"],"a":1,"exp":"stream 的定义就是有序队列，同流内串行。不同 stream 之间默认无顺序、可并发（受 SM 资源限制）。要在两个 stream 之间建立依赖，用 cudaEventRecord + cudaStreamWaitEvent。这也是「多流重叠拷贝与计算」的基础。","level":"高频","tags":["CUDA","流"]}],"virt":[{"id":"v-001","q":"Intel VT-x 中 VMCS（Virtual Machine Control Structure）的作用是？","opts":["保存虚拟机的磁盘镜像","每 vCPU 一份的控制结构，保存 guest/host 状态区、VM-exit/VM-entry 控制字段与 exit 原因","CPU 与 GPU 之间的通信缓冲区","EPT 页表的备份"],"a":1,"exp":"VMCS 由 VMPTRLD 装载，物理上每 vCPU 一个。它记录 guest 的寄存器状态、host 的恢复状态、哪些指令/事件触发 VM-exit，以及退出原因（exit qualification）。VMREAD/VMWRITE 访问。VMX 的 root（host）与 non-root（guest）两种操作模式之间靠 VMLAUNCH/VMRESUME 与 VM-exit 切换。","level":"高频","tags":["VT-x","CPU 虚拟化"]},{"id":"v-002","q":"EPT（Extended Page Tables）解决的核心问题是？","opts":["让 guest 物理地址无需软件介入即可二次翻译到 host 物理地址，消除传统影子页表的 VM-exit 开销","加密 guest 内存","减少 TLB 容量需求","让 DMA 绕过 IOMMU"],"a":0,"exp":"没有 EPT 时，guest 页表里的 GPA 需要在 host 侧维护影子页表（shadow page table），每次 guest 改页表都要 VM-exit 去同步，代价极高。EPT 让硬件做 GPA→HPA 的第二层翻译，guest 可以完全拥有自己的页表。AMD 的对应技术叫 NPT。代价是 EPT violation 的处理，以及 TLB 需要两级遍历。","level":"高频","tags":["EPT","内存虚拟化"]},{"id":"v-003","q":"KVM 与 QEMU 的分工，下列描述最准确的是？","opts":["QEMU 是内核模块，KVM 是用户态进程","KVM 是内核模块，提供 /dev/kvm 与 vCPU 执行、内存映射、中断注入等原语；QEMU 是用户态 VMM，负责设备模拟、磁盘镜像、生命周期与命令行","两者功能重叠，可任选其一","KVM 负责设备模拟，QEMU 负责 vCPU 调度"],"a":1,"exp":"KVM 本身不做设备模拟，它把 CPU 虚拟化能力（VT-x/SVM）包装成 ioctl：创建 VM、创建 vCPU、KVM_RUN 进入 guest。QEMU 用这些 ioctl 跑 vCPU 线程，并在 host 侧模拟网卡、磁盘、芯片组。性能敏感的设备走 virtio，更极致的走 VFIO 直通。KVM 是 hypervisor，QEMU 是 VMM。","level":"高频","tags":["KVM","QEMU"]},{"id":"v-004","q":"virtio 的 split virtqueue 由三部分组成，它们是？","opts":["descriptor table、available ring、used ring","producer、consumer、broker","RX queue、TX queue、control queue","header、payload、checksum"],"a":0,"exp":"descriptor table 描述 buffer 的地址/长度/next 链；avail ring 是驱动告诉设备「哪些描述符可用了」；used ring 是设备回写「哪些已处理完」。两环用 idx 单调递增，用位宽掩码取模，天然无锁（单生产者单消费者）。这种「共享内存 + 通知」的模型避免了每次 IO 的 trap。","level":"高频","tags":["virtio","IO 虚拟化"]},{"id":"v-005","q":"VFIO 直通（device passthrough）依赖的关键硬件能力是？","opts":["EPT","IOMMU（Intel VT-d / AMD-Vi），把设备发起的 DMA 地址翻译并隔离到该 VM 的地址空间","SR-IOV","NUMA"],"a":1,"exp":"直通给 VM 后，设备 DMA 直接读写内存。没有 IOMMU，设备就能 DMA 到任意物理地址，VM 可以借此破坏 host。IOMMU 给设备一张独立的翻译表，把 GPA 限定在该 VM 的范围内，同时拦住非法访问（DMAR fault）。VFIO 在用户态封装了这套机制，配合 VF 中断重映射。SR-IOV 常与 VFIO 一起用，但不是必需品。","level":"高频","tags":["VFIO","IOMMU"]},{"id":"v-006","q":"SR-IOV 中 PF（Physical Function）与 VF（Virtual Function）的关系是？","opts":["PF 是虚拟设备，VF 是物理设备","PF 是具备完整配置能力的物理功能（可创建/管理 VF），VF 是轻量级的虚拟功能，可直接分配给 VM 使用","一个 VF 可对应多个 PF","两者必须同时分配给同一个 VM"],"a":1,"exp":"PF 负责链路与 SR-IOV capability 的管理，通过创建 VF（sriov_numvfs）把硬件切成多个轻量实例。每个 VF 有自己的 PCI 配置空间、BAR、以及独立的队列资源，但共享同一物理端口。VF 直通给 VM 后可以接近裸机性能，代价是失去了 host 侧的软件交换与迁移能力。","level":"中频","tags":["SR-IOV","IO 虚拟化"]},{"id":"v-007","q":"下列哪种情况会触发 VM-exit？","opts":["guest 执行普通的内存读写","guest 执行 CPUID 或访问未配置为直通的 MSR，以及发生 EPT violation","guest 内的用户态进程做系统调用","guest 读取自己的页表"],"a":1,"exp":"VM-exit 由 VMCS 的 execution controls 定义：CPUID、RDMSR/WRMSR（未 bitmap 允许的）、HLT、IO 指令、CR 访问、以及 EPT violation、外部中断（视配置）等。普通内存访问与 guest 内部 syscall 都不会退出——这正是硬件辅助虚拟化高效的原因。VM-exit 是昂贵的，主流优化都围绕削减它的次数。","level":"高频","tags":["VT-x","VM-exit"]},{"id":"v-008","q":"GPU 虚拟化的几种技术路线中，「API remoting」的特点是？","opts":["把整块 GPU 通过 VFIO 直通给一个 VM","在 guest 内拦截图形/CUDA API 调用，序列化后交给 host 或远端执行，guest 里没有真实驱动栈","通过 SR-IOV 切分 SM","用 MIG 做硬件分区"],"a":1,"exp":"典型代表是 NVIDIA vGPU 的部分模式、以及各类远程渲染方案。好处是 VM 可迁移、可超分；坏处是 API 调用需要跨 VM 边界序列化与转发，上下文切换开销大，且必须针对每套 API 做适配。相比之下 passthrough 性能最好但不支持迁移，SR-IOV/MIG 介于两者之间。","level":"中频","tags":["GPU 虚拟化"]},{"id":"v-009","q":"内存气球（ballooning）在虚拟化中的作用是？","opts":["加速内存访问","让 hypervisor 通过 guest 内的气球驱动回收其未使用的物理页，实现内存超分下的动态调整","做内存快照","实现内存加密"],"a":1,"exp":"host 内存紧张时，virtio-balloon 驱动在 guest 内 inflate：申请并「钉住」一批页，把 PFN 报告给 host，host 即可回收这些物理页给别人用。deflate 则归还。它需要 guest 配合，且在 guest 内存压力大时效果有限。这与 KSM 的页合并是两条不同的路线。","level":"中频","tags":["内存虚拟化","balloon"]},{"id":"v-010","q":"vCPU 的 steal time（偷取时间）指的是？","opts":["guest 自己空闲的时间","vCPU 处于可运行状态、但被 host 调度器调度出去未能真正占用物理 CPU 的时间","中断处理占用的时间","guest 内核态执行时间"],"a":1,"exp":"由 KVM 通过 pvclock 的 steal_time 字段暴露给 guest（体现在 /proc/stat 的 steal 列）。steal 高说明物理 CPU 争抢严重或 vCPU 被超额分配。虚拟机里观察到的「CPU 很闲但程序很慢」常常就是这个原因。解决办法是减少 vCPU 超分、绑定 CPU、隔离中断。","level":"中频","tags":["vCPU","性能"]},{"id":"v-011","q":"嵌套虚拟化（nested virtualization）的性能开销主要来自？","opts":["guest 内存更大","L1 hypervisor 自身运行在 L0 的 guest 中，L2 的 VM-exit 需要先陷入 L0 再由 L1 软件模拟，形成双层退出","磁盘 IO 变慢","CPU 频率降低"],"a":1,"exp":"硬件（VMCS shadowing、ARM 的 VHE 等）能减轻但不能消除。L2 guest 的一次敏感操作会 exit 到 L1，若 L1 无法在本地处理，还要再 exit 到 L0，两者之间靠软件模拟 VMCS 的读写。所以嵌套层数越多、开销越非线性增长。EPT 也因此变成两级嵌套翻译。","level":"低频","tags":["嵌套虚拟化"]},{"id":"v-012","q":"virtio 中「通知抑制 / 中断合并」主要用于优化什么？","opts":["减少内存占用","减少 doorbell 与中断的次数，避免每处理一个包就陷入一次，从而降低 CPU 开销","提高网络带宽上限","实现设备热插拔"],"a":1,"exp":"virtqueue 有 EVENT_IDX 等特性，可以让一端声明「攒够 N 个再通知我」，或临时关闭通知。内核的 NAPI 与 virtio 的 tx/rx 中断合并配合，把「每包一中断」变成批量处理。代价是延迟上升，所以低延迟场景（如 DPDK、vhost-user 的 busy polling）会反过来选择关闭中断、改用轮询。","level":"中频","tags":["virtio","性能"]}],"net":[{"id":"n-001","q":"TCP 三次握手中，服务端在收到 SYN 后进入哪个状态？","opts":["ESTABLISHED","SYN_RCVD","LISTEN","CLOSE_WAIT"],"a":1,"exp":"服务端 LISTEN 收到 SYN，回复 SYN+ACK 并进入 SYN_RCVD，收到客户端的 ACK 后转 ESTABLISHED 并放入 accept 队列。这时的半连接放在 syn 队列（syn_table），全连接放在 accept 队列。backlog 溢出时，前者受 tcp_max_syn_backlog 与 syncookies 影响，后者受 listen(fd, backlog) 影响。","level":"高频","tags":["TCP","状态机"]},{"id":"n-002","q":"主动关闭连接的一方为什么需要 TIME_WAIT 状态，并等待 2MSL？","opts":["为了让对端有时间发数据","为了保证最后那个 ACK 能重传（对端重发的 FIN 能被正确回应），并让本连接的旧报文在网络中彻底消失，避免污染使用相同四元组的新连接","为了释放文件描述符","内核实现限制，无实际意义"],"a":1,"exp":"两个目的：一是最后的 ACK 若丢失，对端会重发 FIN，处于 TIME_WAIT 的一方还能重发 ACK；二是 2MSL 足以让本连接的所有报文消亡，防止新连接收到旧连接的迷途报文。代价是大量短连接会堆积 TIME_WAIT 占用端口，可用 SO_REUSEADDR 缓解（它不能消除 TIME_WAIT，只是允许绑定）。","level":"高频","tags":["TCP","TIME_WAIT"]},{"id":"n-003","q":"epoll 相对 select/poll 的核心优势是？","opts":["支持更多协议","内核用红黑树维护关注集、就绪链表返回结果，事件复杂度为 O(就绪数) 而非 O(关注总数)，且无需每次调用重复传入全部 fd 集合","epoll 不需要系统调用","epoll 支持阻塞 IO，select 不支持"],"a":1,"exp":"select 有 FD_SETSIZE=1024 限制且每次调用都要把集合拷进内核、返回后再线性扫描；poll 去掉了 1024 限制但仍需全量拷贝与扫描。epoll 把注册（EPOLL_CTL_ADD）与等待（epoll_wait）分开，回调在事件到来时把 fd 挂到就绪链表，返回的开销与就绪数成正比。注意：epoll 在 fd 极多但几乎全活跃时并不比 poll 快，它的优势在「大量 fd、少量活跃」。","level":"高频","tags":["epoll","IO 多路复用"]},{"id":"n-004","q":"水平触发（LT）与边缘触发（ET）的关键区别是？","opts":["ET 更快，LT 已废弃","LT：只要缓冲区还有数据，每次 epoll_wait 都会返回该 fd；ET：仅在状态变化时通知一次，必须一次读到 EAGAIN，否则剩余数据不再触发","ET 只能用于 UDP","两者只影响写事件"],"a":1,"exp":"ET 要求 fd 是非阻塞的，并且在收到事件后循环 read/write 直到返回 EAGAIN，否则数据会滞留且不再有通知。ET 减少了 epoll_wait 的唤醒次数，但编程错误会直接导致「卡住」。LT 容错性好，代价是可能反复唤醒。Nginx 等高性能服务器普遍用 ET。","level":"高频","tags":["epoll","LT/ET"]},{"id":"n-005","q":"sendfile() 相比 read()+write() 的零拷贝优势体现在？","opts":["不需要系统调用","省去了数据从内核页缓存拷贝到用户缓冲区的那一次拷贝与两次上下文切换，数据直接在内核内部从 page cache 送到 socket 缓冲区","可以压缩数据","绕过 TCP 协议栈"],"a":1,"exp":"read()+write() 要经历：内核→用户、用户→内核 socket buffer，共两次拷贝、四次上下文切换。sendfile 让数据留在内核里，只传描述符。配合网卡的 scatter-gather（DMA gather）甚至可省掉到 socket buffer 的拷贝，即真正的「零拷贝」。splice 则通过管道在不同 fd 间搬数据，适用于非 socket 目标。","level":"高频","tags":["零拷贝","sendfile"]},{"id":"n-006","q":"Linux 收包路径中，NAPI 的作用是？","opts":["提高网卡带宽上限","在中高负载下关闭每包中断，改为轮询（poll）批量收包，避免中断风暴（live-lock）","实现多队列","做报文校验"],"a":1,"exp":"网卡收到包触发硬中断，上半部只做最少的工作（关中断、调度 NAPI），然后让 softirq 里的 poll 方法批量从 ring 里取包，取够预算（net.core.netdev_budget）或取空才重新开中断。这样在高包量时从「每包一中断」变成「一次中断收一批」。RSS/RPS 则是在多核之间分发的互补机制。","level":"中频","tags":["收包路径","NAPI"]},{"id":"n-007","q":"TCP 拥塞控制中，CUBIC 与 BBR 的根本差异是？","opts":["CUBIC 基于丢包信号调整窗口，BBR 基于建模出的带宽与最小 RTT 主动控制发送速率，不把丢包等同于拥塞","BBR 只用于无线网络","CUBIC 是拥塞控制，BBR 是流量整形","两者都是基于丢包的"],"a":1,"exp":"CUBIC（Linux 默认）属于 loss-based：窗口按三次函数增长，丢包即视为拥塞而大幅收缩。在有随机丢包或深缓冲（bufferbloat）的链路上会误判。BBR 维护瓶颈带宽与最小 RTT 的估计，按 BDP 控制 pacing 速率，因此在长肥管道和高丢包链路上表现更好，但公平性与深队列共存时仍有争议。","level":"中频","tags":["TCP","拥塞控制"]},{"id":"n-008","q":"Nagle 算法与延迟 ACK 同时开启时可能造成什么问题？","opts":["带宽利用率下降","小包被积压等待 ACK，而 ACK 又在等待数据或超时，形成互相等待，导致最高约 40ms 的额外延迟","连接无法建立","触发重传风暴"],"a":1,"exp":"Nagle 规定「有未确认数据时不发小包」，延迟 ACK 规定「收到数据后等一小会儿，看能否捎带 ACK」。两者叠加会出现：发送方等 ACK 才发下一个包，接收方等更多数据才发 ACK。延迟敏感的应用（如游戏、RPC）应设 TCP_NODELAY 关闭 Nagle。","level":"中频","tags":["TCP","Nagle"]},{"id":"n-009","q":"RDMA 的核心特征不包括？","opts":["内核旁路（kernel bypass），用户态直接提交工作请求","零拷贝，数据直接在注册内存与网卡之间 DMA","基于可靠的、面向连接的字节流语义","通过 Queue Pair 与 Completion Queue 异步完成"],"a":2,"exp":"RDMA 提供的是消息（message）语义而非 TCP 那样的字节流：Send/Recv 与 Read/Write 操作作用在注册的内存区（MR）上，完成后在 CQ 里产生 CQE。它支持 RC/UC/UD 等传输类型，其中 UD 是不可靠无连接的。核心价值是内核旁路 + 零拷贝，代价是必须预先 pin 内存、不可随意换出。","level":"中频","tags":["RDMA","高性能网络"]},{"id":"n-010","q":"关于 MTU 与 MSS，正确的说法是？","opts":["MTU 是 TCP 层的概念，MSS 是链路层的概念","MTU 是链路层单帧可承载的最大载荷（以太网默认 1500），MSS = MTU − IP 头 − TCP 头，用于 TCP 分段协商","两者数值相同","MSS 由应用层设置"],"a":1,"exp":"以太网 MTU 1500，IPv4 头 20 + TCP 头 20，得 MSS 1460。MSS 在三次握手时通过 SYN 选项协商，取双方较小值。路径 MTU 更小时（如隧道封装）若不分片会丢包并依赖 PMTUD，黑洞场景下常见「能 ping 通但大包卡死」。","level":"中频","tags":["TCP","MTU"]},{"id":"n-011","q":"大量连接处于 CLOSE_WAIT 状态，通常说明？","opts":["网络链路故障","对端已发 FIN，本端应用没有调用 close()，是程序 bug（未关闭 fd 或阻塞在读上）","内核参数配置错误","存在 SYN flood 攻击"],"a":1,"exp":"CLOSE_WAIT 表示被动关闭方已收到 FIN。此时内核已把 EOF 交给应用，剩下的必须由应用 close()。堆积说明应用没有正确处理连接关闭——常见于异常分支漏了 close、或用完 fd 却没归还连接池。TIME_WAIT 多通常是主动关闭量大（正常现象），CLOSE_WAIT 多则几乎一定是自己的代码问题。","level":"高频","tags":["TCP","排障"]},{"id":"n-012","q":"select 的 FD_SETSIZE 默认值是多少？","opts":["256","1024","4096","65535"],"a":1,"exp":"glibc 的 FD_SETSIZE 默认 1024，fd_set 是定长位图。要突破需在编译整个相关库之前重定义它并重新编译，实践中几乎没人这么做，所以高并发一律用 epoll（Linux）/ kqueue（BSD）。注意这只是用户态限制，不是内核限制。","level":"低频","tags":["select","IO 多路复用"]}],"cpp":[{"id":"c-001","q":"含虚函数的类，其实例对象中通常多出什么？","opts":["一张完整的 vtable 副本","一个指向该对象所属类 vtable 的指针（vptr），放在对象起始处","所有虚函数的地址数组","一个引用计数"],"a":1,"exp":"vtable 每类一份（通常在只读数据段），对象里只存 vptr。因此有虚函数的对象至少多一个指针大小（64 位下 8 字节），且这个指针受 ABI 规定位置（Itanium ABI 放在偏移 0）。构造函数里设置 vptr，这也是「构造函数中调用虚函数不会派发到派生类」的原因。","level":"高频","tags":["对象模型","vtable"]},{"id":"c-002","q":"在构造函数和析构函数中调用虚函数，实际会调用到哪个版本？","opts":["始终是派生类的重写版本","构造函数/析构函数自身所在类的那一版，因为此时 vptr 指向的是当前构造/析构层的 vtable","纯虚函数会直接终止程序","编译报错"],"a":1,"exp":"构造基类子对象时 vptr 指向基类 vtable，进入派生类构造体前才被改成派生类 vtable；析构时反过来。所以基类构造里调虚函数只能到基类版本。若该版本是纯虚函数，则是未定义行为（实践中常见链接错误或 pure virtual call 崩溃）。","level":"高频","tags":["对象模型","构造析构"]},{"id":"c-003","q":"以下哪种情况编译器会为类隐式生成拷贝构造函数？","opts":["只要用户声明了析构函数就一定会生成","用户未声明拷贝构造、移动构造、移动赋值、拷贝赋值与析构时，才会隐式生成（拷贝构造被隐式删除的情形除外）","含引用成员的类也会生成","任何类都一定生成"],"a":1,"exp":"声明析构函数、拷贝/移动赋值、或移动构造，都会抑制拷贝构造的隐式生成（但移动构造被抑制时拷贝构造仍会作为 fallback 生成，这一点容易混淆）。含引用成员或 const 成员时，拷贝构造会用成员初始化，但拷贝赋值会被定义为 deleted。C++11 起用 `= default` / `= delete` 显式表达意图最安全。","level":"高频","tags":["特殊成员函数"]},{"id":"c-004","q":"RAII 的本质是什么？","opts":["用 try/catch 捕获所有异常","把资源的生命周期绑定到栈对象的生命周期，构造时获取、析构时释放，借助作用域退出（含异常展开）保证确定性释放","延迟到程序退出时统一释放","使用智能指针"],"a":1,"exp":"关键在「确定性」：栈对象离开作用域必定析构，无论正常返回还是异常展开。std::unique_ptr、std::lock_guard、std::fstream 都是这个模式的封装。它解决的问题是 C 里 goto cleanup 和手工释放的易错性。注意析构函数不应抛异常，否则栈展开中会 terminate。","level":"高频","tags":["RAII","资源管理"]},{"id":"c-005","q":"移动构造函数的参数类型应写成？","opts":["T(T other)","T(T&& other) noexcept","T(const T& other)","T(T* other)"],"a":1,"exp":"右值引用 `T&&` 才能绑定到右值并参与重载决议。加 `noexcept` 极其关键：std::vector 扩容时用 `move_if_noexcept`，若移动构造不是 noexcept，为保证强异常安全会退化成拷贝。移动后源对象要处于「有效但未指定」状态，通常把指针置空。","level":"高频","tags":["移动语义","noexcept"]},{"id":"c-006","q":"std::move 实际做了什么？","opts":["把对象的数据搬到新地址","仅仅是一个到右值引用的 static_cast，本身不产生任何机器指令，真正的资源转移发生在被调用的移动构造/移动赋值里","调用析构函数","分配新内存"],"a":1,"exp":"`std::move(x)` 等价于 `static_cast<T&&>(x)`。它只是把表达式变成右值，让重载决议选中移动版本。若类型没有移动构造，就会 fallback 到拷贝构造——所以「用了 move 就一定快」是错的。传入的是 const 对象时，移动构造也选不中，会拷贝。","level":"高频","tags":["移动语义"]},{"id":"c-007","q":"转发引用（universal reference）在什么条件下成立？","opts":["任何 T&& 都是转发引用","仅当形如 `T&&` 且 T 是模板参数、且没有其他内容（如 `std::vector<T>&&` 不是）时成立，靠引用折叠推导","只在类模板中成立","需要显式标注"],"a":1,"exp":"模板参数推到左值时 T 被推导为 `U&`，`U& &&` 折叠为 `U&`；推到右值时 T 为 `U`，得到 `U&&`。配合 `std::forward<T>` 才能把右值属性原样传出。`auto&&` 也是转发引用。这是完美转发的基础，也是为什么 `std::make_unique` 等工厂函数能同时接受两种值类别。","level":"中频","tags":["模板","完美转发"]},{"id":"c-008","q":"std::atomic<int> 的 ++ 操作默认使用哪种内存序？","opts":["memory_order_relaxed","memory_order_seq_cst","memory_order_acquire","memory_order_release"],"a":1,"exp":"不指定时是 seq_cst，即最严格的「全序 + 同步」语义，性能也最低。纯计数场景可用 relaxed（只保证原子性、不保证顺序）。实现 acquire/release 模式（如发布指针）应用 `store(release)` + `load(acquire)`。x86 上 acquire/release 基本无额外指令（靠强内存模型），ARM 上才需要显式的 `ldar`/`stlr`，这也是跨平台性能差异的来源。","level":"高频","tags":["内存序","并发"]},{"id":"c-009","q":"下列哪一项是未定义行为（UB）？","opts":["有符号整数溢出","无符号整数溢出","对指针做空检查","用 memcpy 拷贝 trivially copyable 类型"],"a":0,"exp":"有符号溢出是 UB，编译器可以假设它不发生，从而把 `if (x + 1 < x)` 判为恒假并删掉。无符号溢出是良定义的回绕（模 2^N）。其他常见 UB：解引用空指针、越界访问、同一表达式内多次修改同一对象、以及数据竞争（非原子变量的并发读写）。","level":"高频","tags":["UB","语言细节"]},{"id":"c-010","q":"结构体 `struct A { char c; int i; char d; };` 在 64 位 x86 上 sizeof 通常是多少？","opts":["6","8","12","16"],"a":2,"exp":"成员按自身对齐要求填充：c 在偏移 0，i 需 4 字节对齐故偏移 4（补 3 字节），d 在偏移 8，结构体整体还需按最大对齐（4）向上取整到 12。这是 ABI 规定的 layout，不是随意选择。把大对齐成员放前面（或按对齐降序排）可以减小体积。`#pragma pack` 能压缩但会导致非对齐访问，在 ARM 上可能触发异常并显著变慢。","level":"高频","tags":["内存布局","对齐"]},{"id":"c-011","q":"shared_ptr 的引用计数是线程安全的，这句话的准确含义是？","opts":["被管理对象的读写是线程安全的","引用计数的增减是原子的，多个线程各自持有 shared_ptr 副本并对其实施拷贝/析构是安全的；但同一个 shared_ptr 实例被多线程同时读写仍然不是","shared_ptr 可以完全替代互斥锁","它可以跨进程共享"],"a":1,"exp":"控制块里的 use_count 用原子操作维护，所以「不同 shared_ptr 副本指向同一对象」的场景安全。但同一个 shared_ptr 对象本身被并发修改（如一个线程 reset、另一个线程读）是数据竞争。被管理的对象更完全没有保护。另外 make_shared 把对象与控制块一次分配，减少一次分配但会让弱引用延长整块内存寿命。","level":"高频","tags":["智能指针","并发"]},{"id":"c-012","q":"weak_ptr 存在的主要目的之一是？","opts":["提高访问速度","打破 shared_ptr 的循环引用，使得互相引用的对象能够被正确释放；使用时通过 lock() 提升为 shared_ptr","实现跨线程共享","节省内存"],"a":1,"exp":"父持有子、子持有父都用 shared_ptr 时，引用计数永远不归零，对象泄漏。把其中一个方向改成 weak_ptr 即可：weak_ptr 不增加强引用计数，只在控制块里增加弱引用计数。观察者模式中的订阅者列表也常用它避免悬挂。lock() 返回 shared_ptr，对象已销毁则返回空。","level":"高频","tags":["智能指针"]},{"id":"c-013","q":"C++ 中 `new` 与 `malloc` 的核心区别不包括？","opts":["new 调用构造函数，malloc 只分配原始内存","new 失败时抛 std::bad_alloc，malloc 返回 NULL","new 是运算符可被重载，malloc 是库函数","new 分配的内存必须用 free 释放"],"a":3,"exp":"配对规则是硬性的：new ↔ delete，new[] ↔ delete[]，malloc ↔ free。混用是 UB（new 的指针用 free 会跳过析构且可能破坏堆元数据）。placement new 只构造不分配，需显式调用析构。new[] 的数组长度记录在实现相关的头部，这也是为什么 delete[] 必须匹配。","level":"高频","tags":["内存管理"]},{"id":"c-014","q":"关于 `std::vector` 的扩容，正确的说法是？","opts":["每次 size 增加就重新分配 1 个元素的空间","容量不足时按倍数（libstdc++ 为 2 倍）申请新内存、搬移/移动元素、释放旧内存，因此 push_back 的均摊复杂度为 O(1)","容量永远不会缩小","扩容时一定调用拷贝构造，不会调用移动构造"],"a":1,"exp":"倍数增长保证均摊 O(1)；元素搬移时会优先用 noexcept 的移动构造。注意扩容会导致所有迭代器、指针、引用失效。容量只能由 reserve/shrink_to_fit 改变，clear() 不释放内存。这也是为什么预先 reserve 能显著减少大对象的重分配。","level":"高频","tags":["STL","vector"]},{"id":"c-015","q":"`inline` 关键字在现代 C++ 中的主要语义是？","opts":["强制编译器内联展开","允许在多个翻译单元中重复定义同一函数（ODR 例外），编译器可自行决定是否真正内联；对性能的影响只是提示","只能用于头文件中的函数","等价于 static"],"a":1,"exp":"现代编译器做内联主要基于优化收益判断（函数体大小、调用频率），`inline` 的「提示」作用微乎其微。它的真正用途是让定义放在头文件里而多个 TU 都能包含——C++17 的 `inline 变量` 同理。类内定义的成员函数隐式 inline。","level":"中频","tags":["语言细节","链接"]},{"id":"c-016","q":"数据竞争（data race）在 C++ 标准中意味着什么？","opts":["性能下降","两个线程并发访问同一内存位置、至少一个为写、且没有同步关系——这属于未定义行为，不只是「结果可能不对」","一定导致崩溃","只影响可移植性"],"a":1,"exp":"C++ 内存模型明确规定数据竞争是 UB，编译器可以假设它不存在而做出任意优化（例如把循环里的读取提到外面、或彻底删掉）。实践中表现为「换个优化级别结果就变了」。正确做法是用 std::atomic 或互斥量建立 happens-before；`volatile` 不能解决这个问题，它只阻止编译器优化，不提供原子性与内存序。","level":"高频","tags":["并发","UB"]}],"python":[{"id":"p-001","q":"CPython 的 GIL 到底保证了什么？","opts":["保证了所有 Python 对象的读写都是原子的","保证同一时刻只有一个线程在执行 Python 字节码，因此纯 Python 计算密集任务无法靠多线程获得并行加速","保证多线程程序不需要任何锁","保证解释器进程内只有一个线程"],"a":1,"exp":"GIL 是一把保护解释器内部状态（包括引用计数）的全局互斥锁，线程必须持有它才能执行字节码。它让「单个 bytecode 层面」的操作是原子的，但一条 Python 语句通常对应多条 bytecode，`x += 1` 依然会丢更新。计算密集用 multiprocessing 或 C 扩展里释放 GIL；IO 密集因为会主动放锁，多线程仍然有效。","level":"高频","tags":["GIL","并发"]},{"id":"p-002","q":"关于 `is` 与 `==`，正确的说法是？","opts":["两者完全等价","`==` 走 `__eq__` 做值比较，`is` 比较对象的身份（id）；小整数与部分字符串因缓存可能 `is` 为真，但不能依赖","`is` 比 `==` 慢，因为它要比较内容","`is` 只能用于数字"],"a":1,"exp":"CPython 缓存了 -5..256 的整数和部分短字符串（interned），所以 `a = 256; b = 256; a is b` 为真，换成 257 就不保证。这是实现细节，不是语言保证。判断 None 必须用 `is None`（None 是单例）；比较值一律用 `==`。可变对象用 `id()` 观察，同一对象的身份才相等。","level":"高频","tags":["对象模型"]},{"id":"p-003","q":"CPython 的内存回收主要依赖什么机制？","opts":["只有引用计数","引用计数为主（计数归零立即释放），辅以分代垃圾回收器处理循环引用","标记-清除","分代复制"],"a":1,"exp":"引用计数带来确定性释放（离开作用域就回收），但无法处理环：A 引用 B、B 引用 A 时计数永不归零。于是有 cyclic GC，按存活时间分为三代，阈值默认 `(700, 10, 10)`——第 0 代净增 700 次分配触发一次，第 0 代回收 10 次触发一次第 1 代，依次类推。gen0 里的对象超过阈值会晋升到 gen1。","level":"高频","tags":["内存管理","GC"]},{"id":"p-004","q":"生成器函数（含 `yield`）调用后返回的是什么？","opts":["一个元组","一个生成器对象，持有栈帧与挂起状态，每次 `next()` 从上次 `yield` 处继续执行","一次执行完所有代码","一个列表"],"a":1,"exp":"生成器对象保存了帧对象（局部变量、指令指针），所以是「可恢复」的，内存开销与产出数量无关。`yield` 处会把控制权交还调用方并保存现场，下一次 `next()` 从该点恢复。函数体在第一次 `next()` 之前根本不执行——这也解释了为什么生成器里的异常要到迭代时才暴露。`yield from` 把委托给子生成器。","level":"高频","tags":["生成器","迭代器"]},{"id":"p-005","q":"在 Python C 扩展中，长时间计算时为什么要主动释放 GIL？","opts":["释放 GIL 能提高单线程性能","持有 GIL 期间其他 Python 线程完全无法执行，用 `Py_BEGIN_ALLOW_THREADS` / `Py_END_ALLOW_THREADS` 包住不碰 Python 对象的重计算，可以真正并行","释放 GIL 会自动加锁保护数据","不释放会导致内存泄漏"],"a":1,"exp":"C 扩展进入时默认持有 GIL。做纯 C 计算（不访问 PyObject）时把它放掉，其他线程才能跑；返回前必须重新获取。NumPy、PyTorch 的算子实现里大量使用这个模式。代价是：释放期间不能调用任何 Python C API（含引用计数操作），否则数据竞争。","level":"中频","tags":["C 扩展","GIL"]},{"id":"p-006","q":"PyTorch 的 Python 层与 C++ 后端是什么关系？","opts":["Python 层实现全部计算逻辑","Python 层是薄前端（张量对象、autograd 图、调度），真正的算子与内核在 C++/CUDA 的 ATen 与后端库里；Python 调用会释放 GIL","C++ 层只是胶水","两者互相独立，各自实现一套"],"a":1,"exp":"`torch.Tensor` 在 Python 侧是一个带元数据的包装，底层 `TensorImpl` 与存储都在 C++。`aten::` 算子由 dispatcher 分发到 CPU/CUDA 实现。PyTorch 从 Python 进入 C++ 时释放 GIL，所以 Python 线程能并发提交 kernel，也不会阻塞其他线程。理解这层边界，才能解释「为何小张量 Python 开销占比高」。","level":"中频","tags":["PyTorch","架构"]},{"id":"p-007","q":"Python 中 `a = [1, 2]; b = a; b.append(3)` 之后 `a` 是什么？","opts":["[1, 2]","[1, 2, 3]","报错","None"],"a":1,"exp":"赋值只是把名字绑定到同一个对象，`a` 与 `b` 指向同一个 list，`id(a) == id(b)`。所以通过 `b` 修改会影响 `a`。要复制得用 `a.copy()`、`a[:]` 或 `copy.deepcopy()`（后者处理嵌套可变对象）。`is` 可以验证两者身份相同。这也是默认参数写成 `def f(x=[])` 会共享同一列表的原因。","level":"高频","tags":["对象模型","引用"]},{"id":"p-008","q":"下列哪种集合类型是可哈希（可作为 dict 的 key）的？","opts":["list","dict","tuple（且元素全可哈希）","set"],"a":2,"exp":"可哈希要求 `__hash__` 与 `__eq__` 一致、且对象不可变。list/dict/set 可变，不可哈希；tuple 不可变，元素都可哈希时才能做 key；frozenset 也可以。用户自定义类默认按 `id` 哈希，若重写 `__eq__` 而不重写 `__hash__`，该类的 `__hash__` 会被置为 None，变得不可哈希。","level":"高频","tags":["哈希","字典"]},{"id":"p-009","q":"`with` 语句背后的协议是？","opts":["`__init__` / `__del__`","上下文管理器协议：`__enter__` 返回值绑定给 as 目标，退出时无论正常还是异常都会调用 `__exit__`；`__exit__` 返回真会吞掉异常","`__call__`","`__iter__` / `__next__`"],"a":1,"exp":"`__exit__(exc_type, exc_val, tb)` 一定被调用，这就是确定性清理的来源——等价于 try/finally，但可复用。文件、锁、数据库事务都用它。用 `contextlib.contextmanager` 装饰生成器也可以实现：`yield` 之前是 enter，之后是 exit。注意 `__exit__` 返回 True 会抑制异常，这常常是坑。","level":"高频","tags":["上下文管理器"]},{"id":"p-010","q":"`asyncio` 的并发模型属于哪一类？","opts":["抢占式多线程","单线程事件循环 + 协程，靠 `await` 在 IO 等待点主动让出控制权，实现协作式并发","多进程并行","靠 GIL 实现并行"],"a":1,"exp":"事件循环在一个线程里调度所有协程，`await` 挂起处才切换，不存在抢占。适合高并发 IO（大量连接、每个都不算 CPU 重）。协程是「协作式」的：一个协程里写死循环不放 await，整个循环都会卡住。CPU 密集要用 `run_in_executor` 丢到线程/进程池，否则会阻塞 loop。","level":"高频","tags":["asyncio","并发"]},{"id":"p-011","q":"关于 Python 的 `__slots__`，正确的说法是？","opts":["它让类变成不可变","它用固定槽位替代实例 `__dict__`，省下每个实例一个字典的开销，同时禁止动态添加属性","它提高所有方法的执行速度","它只对继承自 object 的新式类无效"],"a":1,"exp":"默认实例属性存在 `__dict__` 里，每个实例至少一个字典。声明 `__slots__ = ('a','b')` 后改为固定偏移，内存显著下降、访问略快，代价是不能新增未声明的属性，也不能和多重继承中带 `__dict__` 的基类共存。适合海量小对象（如坐标点、AST 节点）。具体省多少字节取决于实现，别背数字。","level":"中频","tags":["对象模型","内存"]},{"id":"p-012","q":"`multiprocessing` 相比 `threading` 能绕开 GIL 的原因是？","opts":["多进程不启动解释器","每个子进程有独立的解释器与独立的 GIL，因此可以真正并行执行 Python 字节码；代价是进程间通信与内存不共享","多进程会关闭 GIL","多进程运行在不同机器上"],"a":1,"exp":"GIL 是进程级的，`fork`/`spawn` 出来的子进程各自持有一把。所以 CPU 密集任务用 `ProcessPoolExecutor` 才有加速。但参数必须可 pickle（或走共享内存 `shared_memory`），且创建进程比线程贵得多，任务粒度太小反而是负收益。Linux 上默认 `fork`，Python 3.14 起部分平台默认改为 `forkserver`，涉及多线程时要注意 fork 安全性。","level":"中频","tags":["多进程","GIL"]}],"sysdebug":[{"id":"d-001","q":"线上服务 CPU 使用率异常高，应该怎么开始查？","opts":["直接用 gdb attach 上去打断点单步","先看整体指标（top / perf stat 拿 IPC、上下文切换、cache miss），确认是 CPU 真忙还是等锁、等 IO，再决定用 perf record 还是 off-CPU 分析","重启进程恢复服务再说","直接上 eBPF 写脚本"],"a":1,"exp":"第一步永远是分层定位，不要一上来就 gdb。`top` 看是 us 高还是 sy 高；`perf stat -p <pid> sleep 5` 拿 IPC、context-switch、page-fault、cache-miss。IPC 低说明在等内存/指令cache，sy 很高说明系统调用或内核态热点。只有确定是 on-CPU 热点，`perf record -g` 才有意义。","level":"高频","tags":["perf","方法论"]},{"id":"d-002","q":"`perf record` 采到的火焰图里某个函数占 40%，能直接断定它是瓶颈吗？","opts":["能，占比最高就是瓶颈","不能。采样是概率性的，被 inline 或寄存器分配优化过的代码可能被错误归因到相邻函数；还需看 IPC、cache miss 等指标确认是计算受限还是访存受限","不能，因为 perf 只支持用户态","能，但只对内核态有效"],"a":1,"exp":"采样有一定概率误差：栈回溯在帧指针省略（-fomit-frame-pointer）时依赖 DWARF 展开，展开失败会把开销算到调用者身上。另外「热」不等于「慢」——一个函数占比高可能只是因为它本来就该干很多活。要结合 `perf stat` 判断瓶颈类型，用 `perf annotate` 看是哪条指令。","level":"高频","tags":["perf","火焰图"]},{"id":"d-003","q":"ftrace 的 `function_graph` trace 中，行首的 `+`、`!`、`#` 分别表示什么？","opts":["表示返回值正负","表示函数耗时超过阈值：`+` 约 10µs、`!` 约 100µs、`#` 约 1ms（阈值由 `funcgraph-overhead` 控制，可调）","表示 CPU 核编号","表示函数被调用的次数"],"a":1,"exp":"这些标记是 ftrace 帮你做的一阶过滤，用来在几万行 trace 里快速找出慢函数，不用自己算时间差。默认阈值分档为 10µs / 100µs / 1ms。调优方法：`echo funcgraph-threshold=500 > /sys/kernel/tracing/options/funcgraph-...`（具体选项名以当前内核为准），或直接用 `trace-cmd` 的 `--max-graph-depth` 降噪。","level":"中频","tags":["ftrace","内核调试"]},{"id":"d-004","q":"关于 lockdep，正确的说法是？","opts":["它是运行时死锁检测器，会自动解锁","它在运行时记录锁的获取顺序，通过锁类（lock class）建立依赖图，一旦发现潜在循环依赖就报 splat；它是静态锁序校验，不解决锁竞争性能问题","它只能检测自旋锁，不能检测 mutex","它要求所有锁在同一 CPU 上获取"],"a":1,"exp":"lockdep 检查的是「锁序」而不是「当下是否真死锁」，所以它能在死锁发生前报警。它同时覆盖 spinlock / mutex / rwsem / RCU 等，能报出 ABBA 与自我递归两类问题。注意开启后开销明显（通常是 debug 内核），且动态初始化（`spin_lock_init`）的锁才被跟踪；`raw_spinlock` 与 `spinlock` 是不同 class。","level":"中频","tags":["lockdep","并发"]},{"id":"d-005","q":"内核只能通过打开 `CONFIG_DEBUG_ATOMIC_SLEEP` 才能发现什么类型的 bug？","opts":["内存越界","在原子上下文（中断处理、持有 spinlock、关抢占区）中睡眠，比如在 spinlock 里调用带 GFP_KERNEL 的 kmalloc 或 mutex_lock","文件描述符泄漏","栈溢出"],"a":1,"exp":"原子上下文睡眠会导致调度器在不该调度的地方调度，轻则卡死重则崩溃，且现象极难复现。`CONFIG_DEBUG_ATOMIC_SLEEP` 会在 `might_sleep()` 里检查 `preempt_count` / 中断上下文，直接报 “BUG: sleeping function called from invalid context” 并打印完整栈。KASAN 管的是内存越界，`CONFIG_DEBUG_KMEMLEAK` 管泄漏，三者的职责不要混。","level":"中频","tags":["内核调试","并发"]},{"id":"d-006","q":"内核 panic 或 oops 之后，要事后分析现场，最可靠的做法是？","opts":["在 dmesg 里翻，没有了就没办法","提前配置 kdump（crashkernel 保留内存 + kexec 在崩溃时启动捕获内核），把 vmcore 存下来，再用 crash 工具分析 vmlinux + vmcore","重启后看 /var/log/messages 就够","用 gdb attach 到已崩溃的内核"],"a":1,"exp":"kdump 用 kexec 在 panic 时把第二个内核拉起来，原内核内存完整保留成 vmcore，是所有现场信息的唯一完整来源。`crash vmlinux vmcore` 之后可以 `bt` 看栈、`log` 看 dmesg、`ps` 看任务、`kmem` 看内存。此外 `pstore`/`ramoops` 会在重启后保留 oops 文本，`sysrq` 组合键 `c`（crash）、`t`（任务栈）、`m`（内存）可以在卡死时主动抓现场。","level":"高频","tags":["kdump","内核调试"]},{"id":"d-007","q":"bpftrace 相比 ftrace 的核心优势是？","opts":["性能更好","可以把任意探针（kprobe/tracepoint/uprobe）的事件聚合到内核态 map 里做统计，只把汇总结果带回用户态，因此能以极低开销分析高频事件","只能用于网络","不需要 root"],"a":1,"exp":"ftrace 的 trace buffer 是「逐条记录」，高频事件下几秒就能写出几 GB；bpftrace 的思路是「在内核里先聚合」（count/avg/hist），用户态只拿到几十行结果。所以看单次调用适合 ftrace/perf，做统计分布（延迟分位数、调用次数、size 分布）适合 eBPF。经典一句：`bpftrace -e 'kprobe:vfs_read { @[comm] = count(); }'`。","level":"中频","tags":["eBPF","bpftrace"]},{"id":"d-008","q":"怀疑一次延迟抖动来自「进程等待」，应该看哪类数据？","opts":["on-CPU 火焰图","off-CPU 分析：记录进程离开 CPU 到重新运行的时间（`perf sched`、`offcputime`、`runqlat`），它才能回答「等锁 / 等 IO / 等 CPU 调度」","只看 CPU 使用率","看 cache miss 就够"],"a":1,"exp":"on-CPU 火焰图只覆盖「正在跑」的时间，进程在等锁或等 IO 时不在 CPU 上，在火焰图里完全不可见——这是新手最常踩的坑。off-CPU 可用 bpftrace 的 `offcputime`（按栈聚合阻塞时长）、`runqlat`（等 CPU 调度延迟分布）、`perf sched latency`。有锁的话还要配合 `perf lock` 看具体是哪把锁。","level":"高频","tags":["perf","火焰图","方法论"]},{"id":"d-009","q":"用户态进程内存持续增长，如何区分「泄漏」与「本应如此」？","opts":["看 RSS 大了就是泄漏","先看 VSS/RSS/PSS 的差异与 smaps 的分类统计；确认是堆增长还是 mmap/页缓存；再用 valgrind/memleak 或 ASan 的 LeakSanitizer 定位分配点","直接重启进程","只要 GC 跑过不掉就是泄漏"],"a":1,"exp":"RSS 大不一定是泄漏：glibc malloc 的 arena 与碎片、mmap 的页缓存、线程栈（默认 8MB/线程）都会推高 RSS。`/proc/<pid>/smaps_rollup` 能看到 PSS，容器环境更该看它。确认是堆泄漏后用 valgrind --leak-check=full（慢）、或 ASan 的 LSan（快，编译期插桩）。内核态泄漏用 `CONFIG_DEBUG_KMEMLEAK` + `/sys/kernel/debug/kmemleak`。","level":"中频","tags":["内存","valgrind"]},{"id":"d-010","q":"遇到偶发问题，最有效的推进方式通常是？","opts":["反复重试直到问题消失","把「偶发」变成「必然」：用二分法缩小范围、写最小复现、加日志/加探针统计特征（出现时的参数、负载、时序），必要时用 stress-ng、tc netem、fault injection 放大条件","等它下次再出现","把日志级别调到 debug 全部打开"],"a":1,"exp":"偶发问题的本质是「触发条件概率低」，不是「没有规律」。二分法（按版本、按配置、按线程数、按时间）能把范围压到极小；最小复现让后续调试成本从小时级降到分钟级。放大条件很关键：并发问题加线程数、网络问题注入延迟丢包、内存问题限制 cgroup 内存制造 OOM。`debug` 全开往往因开销过大反而改变时序，让问题更难复现。","level":"高频","tags":["方法论","复现"]},{"id":"d-011","q":"`perf stat` 显示某进程 IPC 只有 0.3（现代 CPU 通常在 1~3），最不可能的解释是？","opts":["大量 cache miss，CPU 大部分时间在等内存","分支预测失败率高，流水线频繁清空","程序是纯计算密集型且数据全在 L1","存在大量系统调用导致用户态/内核态切换"],"a":2,"exp":"纯计算 + 数据全在 L1 恰恰是 IPC 最理想的情况，通常能跑到 2 以上。IPC 低意味着「每个周期退休的指令少」，典型原因是 stall：等内存（`perf stat` 看不出的话要看 `perf c2c` 或 cache 事件）、分支失败（看 `branch-misses`）、长延迟指令（除法、非对齐访存）。用 `perf stat -e cycles,instructions,cache-misses,branch-misses` 一起看才能定性。","level":"中频","tags":["perf","性能"]},{"id":"d-012","q":"排查 GPU 上「训练慢」，第一步正确的切分是？","opts":["直接看单个 kernel 的 SASS 指令","先用 Nsight Systems 看整条时间线：GPU 是空转等数据（CPU/IO 瓶颈、同步点太多），还是 GPU 一直忙（需要 Nsight Compute 深入单 kernel）","先换更快的 GPU 型号","先看理论 FLOPs 峰值"],"a":1,"exp":"这是两套完全不同的工具和结论：如果时间线上 GPU 有大段空洞，问题在数据加载、Python 开销、频繁同步、D2H 拷贝，用 Nsight Compute 看 kernel 一点用没有。只有确认 GPU 利用率高、kernel 背靠背执行，才进入 Nsight Compute 看 SM 利用率、显存带宽、occupancy 这三个指标。顺序搞反是面试里最常见的减分点。","level":"高频","tags":["GPU","Nsight","方法论"]}]}};
